// App.js
import React, { useState, useRef } from 'react';
import ReactDOM from 'react-dom';
import { Unstable_Popover as Popover, ListItem, UnorderedList } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [anchorRect, setAnchorRect] = useState(null);
  const targetRef = useRef(null);

  function handleContextMenu(e) {
    e.preventDefault();
    // record where the user clicked
    const rect = {
      left: e.clientX,
      top: e.clientY,
      width: 0,
      height: 0,
      right: e.clientX,
      bottom: e.clientY,
    };
    // supply a fake getBoundingClientRect for the popover
    targetRef.current = { getBoundingClientRect: () => rect };
    setAnchorRect(rect);
    setMenuOpen(true);
  }

  return (
    <div
      style={{ height: '100vh', width: '100vw', userSelect: 'none' }}
      onContextMenu={handleContextMenu}
    >
      <h2>Right-click anywhere to open context menu</h2>
      {menuOpen && anchorRect && (
        <Popover
          open={menuOpen}
          onClose={() => setMenuOpen(false)}
          align="start"
          shouldFlip={true}
          targetRef={targetRef.current}
        >
          <UnorderedList style={{ margin: 0, padding: '4px 0' }}>
            <ListItem>Share with ▶</ListItem>
            <ListItem>Cut</ListItem>
            <ListItem>Copy</ListItem>
            <ListItem>Paste</ListItem>
            <ListItem>Rename</ListItem>
            <ListItem>Delete</ListItem>
          </UnorderedList>
        </Popover>
      )}
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
